real_t acado_solve_dim88_system( real_t* const A, real_t* const b, int* const rk_perm )
{
real_t det;

int i;
int j;
int k;

int indexMax;

int intSwap;

real_t valueMax;

real_t temp;

for (i = 0; i < 88; ++i)
{
rk_perm[i] = i;
}
det = 1.0000000000000000e+00;
for( i=0; i < (87); i++ ) {
	indexMax = i;
	valueMax = fabs(A[i*88+i]);
	for( j=(i+1); j < 88; j++ ) {
		temp = fabs(A[j*88+i]);
		if( temp > valueMax ) {
			indexMax = j;
			valueMax = temp;
		}
	}
	if( indexMax > i ) {
for (k = 0; k < 88; ++k)
{
	rk_dim88_swap = A[i*88+k];
	A[i*88+k] = A[indexMax*88+k];
	A[indexMax*88+k] = rk_dim88_swap;
}
	rk_dim88_swap = b[i];
	b[i] = b[indexMax];
	b[indexMax] = rk_dim88_swap;
	intSwap = rk_perm[i];
	rk_perm[i] = rk_perm[indexMax];
	rk_perm[indexMax] = intSwap;
	}
	det *= A[i*88+i];
	for( j=i+1; j < 88; j++ ) {
		A[j*88+i] = -A[j*88+i]/A[i*88+i];
		for( k=i+1; k < 88; k++ ) {
			A[j*88+k] += A[j*88+i] * A[i*88+k];
		}
		b[j] += A[j*88+i] * b[i];
	}
}
det *= A[7743];
det = fabs(det);
acado_solve_dim88_triangular( A, b );
return det;
}

